                  (Z_to_bv 64 (needed2 n)) (Z_to_bv 64 8) a4' a5' a6' a7' (Z_to_bv 64 8) (Z_to_bv 64 (needed2 n))
                  (Z_to_bv 64 (rz_size n)) (Z_to_bv 64 n) (Z_to_bv 64 INST) (Z_to_bv 64 (bv_unsigned sp + -2128))
                  (Z_to_bv 64 (0 + - (8))) (Z_to_bv 64 7) (Z_to_bv 64 T) (Z_to_bv 64 1) t3' t4' t5' t6')
             F (Z_to_bv 64 0x4a724) fc None m' (seg_rom asegs)
    /\ munch [(T + 3168, T + 3169); (bv_unsigned sp - 2288, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (bv_unsigned sp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells asegs m' (bv_unsigned sp + -64) [CB 8 jp]
    /\ rw_cells asegs m' (bv_unsigned sp + -72) [C8 (Z_to_bv 64 (bv_unsigned sp))]
    /\ u64arr asegs m' (bv_unsigned sp + -2112) (wr_trace tr tb) /\ length tb = 255%nat
