(* [comment removed for export] *)
Definition malloc_B_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (UB lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 UB) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                  t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 2144, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp).

Lemma malloc_B_spec : forall ra sp gp tp t0 t1 t2 s0' s1' a1 a2 a3 a4 a5 a6 a7 s2' s3' s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    ra0 s0 s1 s2 s3 s4 s5 (F : bvmap 5 word) fc (m : mem) (UB lo : Z) (ws : list word) (w : word) (jp : list byte),
  (0 < UB < 2^64)%Z ->
  stk asegs m lo (bv_unsigned sp + -2144) -> (lo <= bv_unsigned sp + -2144)%Z -> (0x66f000 <= lo)%Z ->
  rw_cells asegs m (bv_unsigned sp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells asegs m (bv_unsigned sp + -64) [CB 8 jp] ->
  rw_cells asegs m (bv_unsigned sp + -72) [C8 (Z_to_bv 64 (bv_unsigned sp))] ->
  u64arr asegs m (bv_unsigned sp + -2112) ws -> length ws = 255%nat ->
  rw_cells asegs m (bv_unsigned sp + -2128) [C8 (Z_to_bv 64 (bv_unsigned sp + -2112)); C8 w] ->
  rw_cells asegs m (bv_unsigned sp + -2144) [C8 (Z_to_bv 64 (bv_unsigned sp)); C8 (Z_to_bv 64 0x68058)] ->
  mem_inv asegs m ->
  evt asegs (malloc_B_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc UB lo m)
    (MS (mkR ra0 (Z_to_bv 64 (bv_unsigned sp + -2144)) gp tp t0 t1 t2 s0' s1' (Z_to_bv 64 UB) a1 a2 a3 a4 a5 a6 a7
             s2' s3' s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x45ebc) fc None m (seg_rom asegs)).
